using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.PermutationSquare;

internal sealed class PermutationSquareFamiliesDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/PermutationSquare/PermutationSquareFamilies.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/Dynamics/archer2026pattern");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Seven explicit permutation families, prefix and position bounds on indecomposable square-avoiders, and the classifications for first entry two and first entry three.",
        H("Explicit families and first-entry bounds"),
        Blocks(
            Node("permutationsquarefamilies-indecomposable-avoiders-definition", "Indecomposable square-avoiders", "indecomposableAvoiders", "For every nonnegative n, the set consists of the nonempty lists that permute one through n, avoid the classical patterns 312 and 54321, have squares avoiding the classical pattern 132, and are indecomposable under direct sum.", DescribeRole.Definition),
            Node("permutationsquarefamilies-b-definition", "Indecomposable counting sequence", "b", "For every nonnegative n, b(n) is the cardinality of the set of nonempty permutations of one through n that avoid 312 and 54321, have squares avoiding 132, and are indecomposable under direct sum.", DescribeRole.Definition),
            Node("permutationsquarefamilies-family-i-definition", "The cyclic shift family I", "familyI", "For a natural number n, familyI(n) lists the integers from two up to n in increasing order followed by one. For n at least two this is a permutation of one through n with first entry two.", DescribeRole.Definition),
            Node("permutationsquarefamilies-family-j-definition", "The single-transposition family J", "familyJ", "For a natural number n, familyJ(n) begins with two, four, three, continues with five up to n in increasing order, and ends with one. For n at least five this is a permutation of one through n with first entry two.", DescribeRole.Definition),
            Node("permutationsquarefamilies-family-k-definition", "The paired-inversion family K", "familyK", "For natural numbers n and j, familyK(n, j) begins with two, lists j plus one adjacent descending pairs (2r + 5, 2r + 4) for r from zero through j, places three next, continues with 2j + 6 up to n in increasing order, and ends with one. For n at least six and j at most the floor of (n minus six) divided by two, this is a permutation of one through n with first entry two.", DescribeRole.Definition),
            Node("permutationsquarefamilies-family-a-definition", "The monotone-middle family A", "familyA", "For a natural number n, familyA(n) begins with four, three, continues with five up to n in increasing order, and ends with two, one. For n at least six this is a permutation of one through n with first entry four.", DescribeRole.Definition),
            Node("permutationsquarefamilies-family-b-definition", "The odd-offset paired family B", "familyB", "For a natural number n, familyB(n) begins with four, three, five, lists floor((n minus five) / 2) adjacent descending pairs (2r + 7, 2r + 6) starting from r equal to zero, and ends with two, one when n is odd and with two, n, one when n is even. For n at least seven this is a permutation of one through n with first entry four.", DescribeRole.Definition),
            Node("permutationsquarefamilies-family-c-definition", "The even-offset paired family C", "familyC", "For a natural number n, familyC(n) begins with four, three, lists floor((n minus four) / 2) adjacent descending pairs (2r + 6, 2r + 5) starting from r equal to zero, and ends with two, one when n is even and with two, n, one when n is odd. For n at least four this is a permutation of one through n with first entry four.", DescribeRole.Definition),
            Node("permutationsquarefamilies-family-d-definition", "The exceptional prefix family D", "familyD", "For a natural number n, familyD(n) begins with four, three, six, seven, five, continues with eight up to n in increasing order, and ends with two, one. For n at least nine this is a permutation of one through n with first entry four.", DescribeRole.Definition),
            Node("permutationsquarefamilies-indecomposable-shape-and-prefix-iff-theorem", "Prefix criterion and structural bounds on indecomposable square-avoiders", "indecomposable_shape_and_prefix_iff", "The count b(0) vanishes, and for every positive n the nonempty condition in indecomposableAvoiders(n) is redundant because every permutation of one through n has length n. A permutation p of one through n is indecomposable under direct sum if and only if no proper positive prefix of length k maps one through k onto itself, and every permutation of one through n with n positive whose last entry is one is indecomposable. Moreover, for every n at least two and every p in indecomposableAvoiders(n) with first entry m, one-based position posN of the maximum entry n, and square q: p ends in one; m lies between two and four inclusive, every value from two through m minus one lies strictly right of position one, and the values from two through m minus one appear in strictly reverse order from left to right; q has value one at position posN, has value m at position n, increases strictly on positions after posN, and forces n + 1 <= posN + m together with posN >= n - m + 1, posN >= n - 3, and posN <= n - 1, with posN equal to n minus one whenever m equals two; and p decreases strictly on positions after posN.", DescribeRole.Theorem),
            Node("permutationsquarefamilies-seven-families-admissible-and-distinct-theorem", "Membership and pairwise distinctness of the seven families", "seven_families_admissible_and_distinct", "Each of the seven explicit families belongs to indecomposableAvoiders(n) on its parameter domain: familyI(n) for n at least two, familyJ(n) for n at least five, familyK(n, j) for n at least six and j at most floor((n minus six) / 2), familyA(n) for n at least six, familyB(n) for n at least seven, familyC(n) for n at least four, and familyD(n) for n at least nine. On the domain of familyK, distinct indices j1 and j2 produce distinct permutations, and any two members chosen from distinct families among I, J, K, A, B, C, and D at the same length n on their common domain are distinct.", DescribeRole.Theorem),
            Node("permutationsquarefamilies-first-entry-two-and-three-classification-theorem", "Classification for first entry two and nonexistence for first entry three", "first_entry_two_and_three_classification", "For every natural number n at least four, an element p of indecomposableAvoiders(n) has first entry two if and only if p equals familyI(n), or n is at least five and p equals familyJ(n), or n is at least six and p equals familyK(n, j) for some j at most floor((n minus six) / 2); consequently the subset of indecomposableAvoiders(n) with first entry two has cardinality one when n equals four and floor(n / 2) when n is at least five. For every natural number n at least five, no element of indecomposableAvoiders(n) has first entry three.", DescribeRole.Theorem)
        ), []));

    private static DocumentBlock Node(string id, string title, string declaration, string prose,
        DescribeRole role, OpenProblemResolutionClaim? resolution = null) =>
        Describe.Lean(DescribeId.Create(id), DeclarationHandle.Create(Prefix + declaration),
            H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(Source),
            Blocks(Paragraph(Text(prose))), role, resolution);
}
